import{z as l,x as s,o as A,c as p,q as B,j as i,D as E,d as n,s as t,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"实证设计规范与收束","description":"","frontmatter":{"title":"实证设计规范与收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pm-specification-map.md","filePath":"econ/pm-specification-map.md","lastUpdated":1791413859000}'),d={name:"econ/pm-specification-map.md"};function m(C,a,c,h,D,f){const o=s("Mermaid");return A(),p("div",null,[a[2]||(a[2]=B('<h1 id="实证设计规范与收束" tabindex="-1">实证设计规范与收束 <a class="header-anchor" href="#实证设计规范与收束" aria-label="Permalink to &quot;实证设计规范与收束&quot;">​</a></h1><div class="epigraph"><p>实证失败大多不在估计量，而在规范：目标没钉、搜索无记录、幸存者上桌、数据不可复现——四样都不需要新技术来治，需要的是流程。</p><footer>—— 据 Simonsohn, Simmons and Nelson, Specification Curve Analysis, Nature Human Behaviour 2020；Gelman and Loken 2014 整理</footer></div><p><a href="/econ/pm-text-as-data">上一课</a>把文本量钉在测量三问与点-in-time 上。本课是「预测与机器学习计量」的最后一课，本课程到此收束：前六课给了评估协议（SPA、PIT、条件评估）、生产工具（稀疏方法、正则化推断）、因果装置（元学习器、DML、文本测量），本课把它们收成一份可执行的规范——目标怎么声明、主结果怎么保护、稳健性怎么报、证据怎么存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规范缺失有四类伤。目标未声明：预测与因果混线，预测指标验收效应模型。规格搜索无记录：试过的规格只有幸存者上桌——Gelman–Loken 称之为「分叉小径的花园」，显著性成了分析路径的属性。主结果事后搬家：预分析定的终点，写报告时换成显著的那个。数据与代码不可复现：快照、种子、环境缺失，结论无法被审计。四类伤的共同点：没有一类能靠换更高级的估计量来治。</p><p><span class="marginnote">直觉类比：「分叉小径的花园」像走廊里布满岔路，每条岔路尽头都挂着一块「显著」的牌子。牌子属于你走的那条路径，不属于花园本身——只带一张岔路尽头的纪念照回来，当成整个花园的风景照发表，就是幸存者偏差。</span></p><h3 id="双轨与三件套" tabindex="-1">双轨与三件套 <a class="header-anchor" href="#双轨与三件套" aria-label="Permalink to &quot;双轨与三件套&quot;">​</a></h3><p>生产分双轨。预测轨按<a href="/econ/pm-regularized-econ">第三课</a>的协议走：样本外窗口、<a href="/econ/pm-forecast-eval-deep">多模型 SPA</a>、校准、组合基线。因果轨按识别声明、得分或设计、异质与政策映射走，识别假设在估计之前写下。两轨的目标声明写在分析第一格。主结果保护：预分析计划先写终点；规格曲线把合理规格全集的效应分布画出来，报「显著的比例与效应的形状」，不挑幸存者。多重检验纪律接<a href="/econ/multiple-testing-econ">多重检验</a>：族内校正（Holm、Benjamini–Hochberg、Romano–Wolf），探索性结果明确标注。可复现三件套：点-in-time 数据快照、随机种子与锁定环境、从原始数据到表格的自动化管道。</p><p><span class="marginnote">规格曲线的读法：结论的稳健性是「全规格分布的位置」，不是「有没有一个显著的」。画出来之后，只在两成规格里显著的效应与九成规格里同号的效应，证据等级完全不同——这一步不加任何新估计，只把研究者自由度从看不见变成分布。</span></p><p><span class="marginnote">术语翻译：预注册就是在动手分析前，把「研究什么、终点是哪个、怎么检验」写成带时间戳的公开承诺；规格曲线则是把所有合理规格的结果一齐画出来看分布。两者合起来治同一个病——让「什么时候做的决定」无法事后改口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程一页纸。第一行写目标：预测轨还是因果轨，参数是哪一个。第二行写设计与数据：识别假设或样本外协议、窗口、快照日期。第三行写主结果与验证规则：终点、校正方法、规格全集的定义。第四行才是估计与报告：效应量加不确定性加决策含义一行；预测模型报校准与经济价值两行；所有转换（裁剪、缩尾、聚合、词典更换）登记在案。越出流程的探索照做，但输出必须标注「探索性」，不得进入结论段。</p>',12)),(A(),i(r,null,{default:E(()=>[t(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E7%AC%AC%E4%B8%80%E8%A1%8C%3A%20%E7%9B%AE%E6%A0%87%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20D%5B%22%E7%AC%AC%E4%BA%8C%E8%A1%8C%3A%20%E8%AE%BE%E8%AE%A1%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%22%5D%0A%20%20D%20--%3E%20R%5B%22%E7%AC%AC%E4%B8%89%E8%A1%8C%3A%20%E4%B8%BB%E7%BB%93%E6%9E%9C%E4%B8%8E%E6%A0%A1%E6%AD%A3%E8%A7%84%E5%88%99%22%5D%0A%20%20R%20--%3E%20E%5B%22%E7%AC%AC%E5%9B%9B%E8%A1%8C%3A%20%E4%BC%B0%E8%AE%A1%E4%B8%8E%E6%8A%A5%E5%91%8A%22%5D%0A%20%20E%20--%3E%20C%7B%22%E9%80%9A%E8%BF%87%E6%A0%A1%E6%AD%A3%E4%B8%8E%E8%A7%84%E6%A0%BC%E6%9B%B2%E7%BA%BF%3F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20PUB%5B%22%E8%BF%9B%E5%85%A5%E7%BB%93%E8%AE%BA%E6%AE%B5%22%5D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20EXP%5B%22%E6%A0%87%E6%B3%A8%E6%8E%A2%E7%B4%A2%E6%80%A7%2C%20%E5%AD%98%E6%A1%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"规范是统计装置的乘数：DM 与 SPA 假设评估窗口诚实，DML 假设控制池预先声明，文本测量假设点-in-time——前六课的每个装置都吃规范红利，也都被规范缺失摧毁。规格曲线的机制是把自由度显形：显著性在全规格分布上的位置才是证据；预注册把「什么时候定的」钉死，事后搬家无处发生。可复现三件套让审计成为可能：审查者能沿管道重跑出同一张表，争论才落在判据上，不是数据上。",-1)),a[5]||(a[5]=e("p",null,"四类伤与各自的处方对照：",-1)),(A(),i(r,null,{default:E(()=>[t(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20W1%5B%22%E4%BC%A4%E4%B8%80%EF%BC%9A%E7%9B%AE%E6%A0%87%E6%9C%AA%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20R1%5B%22%E7%AC%AC%E4%B8%80%E8%A1%8C%E5%86%99%E6%98%8E%E9%A2%84%E6%B5%8B%E8%BD%A8%E6%88%96%E5%9B%A0%E6%9E%9C%E8%BD%A8%22%5D%0A%20%20W2%5B%22%E4%BC%A4%E4%BA%8C%EF%BC%9A%E8%A7%84%E6%A0%BC%E6%90%9C%E7%B4%A2%E6%97%A0%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20R2%5B%22%E8%A7%84%E6%A0%BC%E6%9B%B2%E7%BA%BF%E6%8A%A5%E5%85%A8%E8%A7%84%E6%A0%BC%E5%88%86%E5%B8%83%22%5D%0A%20%20W3%5B%22%E4%BC%A4%E4%B8%89%EF%BC%9A%E4%B8%BB%E7%BB%93%E6%9E%9C%E4%BA%8B%E5%90%8E%E6%90%AC%E5%AE%B6%22%5D%20--%3E%20R3%5B%22%E9%A2%84%E5%88%86%E6%9E%90%E8%AE%A1%E5%88%92%E9%92%89%E6%AD%BB%E7%BB%88%E7%82%B9%22%5D%0A%20%20W4%5B%22%E4%BC%A4%E5%9B%9B%EF%BC%9A%E6%95%B0%E6%8D%AE%E4%BB%A3%E7%A0%81%E4%B8%8D%E5%8F%AF%E5%A4%8D%E7%8E%B0%22%5D%20--%3E%20R4%5B%22%E5%BF%AB%E7%85%A7%E3%80%81%E7%A7%8D%E5%AD%90%E4%B8%8E%E8%87%AA%E5%8A%A8%E5%8C%96%E7%AE%A1%E9%81%93%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>课程收束在此完成：从<a href="/econ/pm-forecast-eval-deep">预测评估的深化</a>的损失差协议出发，经<a href="/econ/pm-sparse-methods">稀疏方法</a>与正则化的推断约束预测器，经<a href="/econ/pm-ml-causal-deep">机器学习与因果的深化</a>与<a href="/econ/pm-dml-deep">Double ML 的深入</a>把工具送进反事实，经<a href="/econ/pm-text-as-data">文本作为数据</a>扩展数据形态——机器学习没有替计量经济学回答识别问题，它把每个经典估计量的讨厌函数位次填得更满；填得再满，目标声明、主结果保护与可复现三件套仍是那道闸门。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>规范不救识别错误：假设清单错，流程再干净也是干净的错。预注册压抑探索，探索要留出并标注，探索发现的检验换新数据做。规范有成本，小样本与快速迭代按比例裁剪——但「按比例」的判断本身要预先声明，不能事后援引。大模型时代文本与代码的复现边界还在收紧：模型版本、解码参数都进三件套，否则管道不可重放。</p><p><span class="marginnote">常见误区：以为规范是「多算几遍更稳妥」的繁文缛节。方向恰好相反——规范限制的是你砍掉不想要的结果的自由。没有这道闸，DM、DML、文本测量每个装置的假设都在暗中失守，换再高级的估计量也救不回来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实证第一行是目标声明：预测轨与因果轨分开跑，指标与验证各自独立。</li><li>主结果用预分析计划保护；规格曲线报全规格分布，不报幸存者。</li><li>多重检验校正、点-in-time 快照、种子与管道复现是三件套，缺一即规范缺失。</li><li>本课程到此收束：从 DM 的损失差到 DML 的正交得分再到文本测量，机器学习加深了计量的每个装置，识别与规范的闸门一道未变。</li><li>出处：Simonsohn, Simmons and Nelson, <em>Nature Human Behaviour</em> 2020；Gelman and Loken 2014；据 Diebold and Mariano 1995、Chernozhukov et al. 2018、Gentzkow, Kelly and Taddy 2019 整理。</li></ul>',6))])}const b=l(d,[["render",m]]);export{_ as __pageData,b as default};
